arguments.sql:
SELECT COUNT(*) AS hydrogen_bond_count
FROM bond
WHERE molecule_id = (
    SELECT molecule_id FROM atom WHERE element = 'Y'
)
AND (
    bond_id IN (
        SELECT bond_id FROM atom AS a1
        JOIN bond AS b1 ON (a1.atom_id = b1.bond_id OR a1.atom_id = b1.molecule_id)
        WHERE a1.element = 'H'
    )
);

